#include "93t4hhss.vca/js/interface/menu.js"	// vERP_2_app

// Preparar el control menú
var formulario = theRoot.dataView();
var menu = formulario.control("MEN_APP");

// Leer el ítem seleccionado y extraer el tipo y la acción o proceso
var item = menu.currentItem();
if (item)
{
	var tipo = item.text(1);
	var opcion = item.text(2);
};
// Ejecutar la acción o proceso correspondiente
switch(tipo)
{
	case "A": // Ejecutar acción
		theMainWindow.runAction(opcion);
		break;
	case "P": // Ejecutar proceso
		theRoot.runProcess(opcion);
		break;
	case "C": // Cambiar de menú
		cargarMenu(opcion);
		break;
	case "M": // Opción menu que abre o cierra la rama del arbol
		if(item.isExpanded()) {
			menu.collapseItem(item);	// Si la rama esta abierta, la cerramos
		} else {
			menu.expandItem(item);		// Si la rama esta cerrada la abrimos
		};
		break;
	default: // Cargar menú configurado en la variable global CUR_MEN (Menú en curso)
		cargarMenu(theApp.globalVarToString("sygemat_corralon_dat/CUR_MEN"));
		break;
};

