// ----------------------------------------------------------
// Log de usuarios concurrentes. Fijar el estado de la sesión
// ----------------------------------------------------------
importClass("VProcess");

// Se realiza el control si el log de usuario concurrente está activo
if (theApp.globalVarToBool("sygemat_corralon_dat/LUC_ON") == true)
{
	// Si el contador de sets está a cero, se ejecuta el control de estado de la sesión
	var contadorsets = theRoot.varToInt("CNT_TIM");
	if (contadorsets < 1)
	{
		// Se ejecuta el proceso de estado de actividad de la sesión para mantenerla activa
		var proceso = new VProcess(theRoot);
		proceso.setProcess("sygemat_corralon_dat/LUC_W_ACT");
		proceso.setVar("ID_SES", theApp.globalVarToString("sygemat_corralon_dat/CUR_ID_SES"));
		proceso.setVar("EMP", theApp.globalVarToString("sygemat_corralon_dat/EMP_REA_ID"));
		proceso.setVar("USR", theApp.globalVarToInt("sygemat_corralon_dat/CUR_USR_ID"));
		proceso.setVar("LOG", theApp.globalVarToString("sygemat_corralon_dat/LOG_SES"));
		proceso.setVar("FIN", false);
		proceso.exec(VProcess.RunInServer);
		var fin     = proceso.varToBool("FIN");
		var mensaje = proceso.varToBool("MSG");
		theApp.setGlobalVar("sygemat_corralon_dat/LOG_SES", "");

		// Si se recibe FIN a 1 se muestra el mensaje y se cierra la aplicación
		if (fin == true)
		{
			theMainWindow.runAction("sygemat_corralon_app/CRR");
		};

		// Se asigna al contador el valor de minutos de demora hasta el siguiente control de estado
		contadorsets = theApp.globalVarToInt("sygemat_corralon_dat/LUC_MIN_CON");	
	};

	// Se decrementa el contador de sets
	contadorsets--
	theRoot.setVar("CNT_TIM", contadorsets);
}
